mapper.select:
SELECT EXISTS (
SELECT 1 FROM tool_call t JOIN agent_run r ON r.enterprise_id = t.enterprise_id AND r.id = t.run_id
WHERE t.enterprise_id = #{enterprise} AND t.actor_user_id = #{user} AND r.user_id = #{user}
AND r.conversation_id = #{conversation} AND t.framework_session_id = #{session}
AND t.resource_kind IN ('agent', 'workflow')
AND ((t.status IN ('succeeded','failed') AND JSON_EXTRACT(t.result_redacted_json, '$.workspaceVersion') IS NOT NULL)
OR (t.status = 'unknown' AND t.operation_class != 'read' AND t.submitted_at IS NOT NULL))
)

SELECT t.* FROM tool_call t JOIN (
SELECT id FROM agent_run WHERE enterprise_id = #{enterpriseId} AND conversation_id = #{conversationId} AND user_id =
#{userId}
ORDER BY created_at DESC, id DESC LIMIT #{recentRuns}
) recent ON recent.id = t.run_id
WHERE t.enterprise_id = #{enterpriseId}
AND (t.resource_kind IN ('knowledge','data') OR (t.resource_kind IN ('agent','workflow') AND t.tool_name IN
('read_file','grep_files','list_files','write_file','edit_file','execute','export_file','read_agent_spawn_result','read_agent_send_result','read_workflow_result')))
AND t.status IN ('succeeded','failed')
ORDER BY t.created_at, t.id

SELECT EXISTS (SELECT 1 FROM tool_call t JOIN run_approval a ON a.enterprise_id = t.enterprise_id AND a.tool_call_id
= t.id
WHERE t.enterprise_id = #{enterpriseId} AND t.run_id = #{id} AND t.resource_id = #{resource}
AND t.resource_version_id <=> #{version} AND t.plugin_tool_id <=> #{tool} AND t.tool_name = #{name}
AND t.argument_hash = #{arguments} AND a.status = 'rejected')

mapper.update:
UPDATE tool_call SET status = 'running', lease_version = #{lease}, started_at = COALESCE(started_at, #{now}),
updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND status IN ('prepared','waiting_approval')

UPDATE tool_call SET submitted_at = COALESCE(submitted_at, #{now}), attempt_count = attempt_count + 1, updated_at =
#{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND status = 'running' AND lease_version = #{lease}

UPDATE tool_call SET status = #{status}, result_encrypted_json = #{value}, result_redacted_json = #{value2},
error_code = #{code}, error_summary = #{error},
finished_at = #{now}, duration_ms = IF(#{status} = 'unknown', NULL, IF(started_at IS NULL, 0, GREATEST(0,
TIMESTAMPDIFF(MICROSECOND, started_at, #{now}) DIV 1000))), updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND status IN ('prepared','waiting_approval','running') AND
lease_version = #{leaseVersion}
